function focusGeneratedContent(target, opts={}){
  if(!target) return false;
  const el=typeof target==='string' ? document.querySelector(target) : target;
  if(!el) return false;
  const block=opts.block||'center';
  try{ el.scrollIntoView({behavior:'smooth',block,inline:'nearest'}); }
  catch(_){ try{el.scrollIntoView(true);}catch(e){} }
  if(opts.flash!==false){ el.classList.add('gs-flash'); setTimeout(()=>el.classList.remove('gs-flash'),1600); }
  return true;
}
function queueGenerationFocus(target, delay=70){
  _generationFocusPending=target;
  clearTimeout(_generationFocusTimer);
  _generationFocusTimer=setTimeout(()=>{
    const t=_generationFocusPending; _generationFocusPending=null;
    focusGeneratedContent(t,{block:'center'});
  },Math.max(0,delay));
}
function inferGenerationFocusTarget(btn){
  if(!btn) return null;
  if(btn.dataset && btn.dataset.generationFocus) return btn.dataset.generationFocus;
  const sec=btn.closest('.flow-sec');
  if(sec){
    const n=sec.dataset && sec.dataset.flow;
    /* 返回稳定选择器，而不是旧 DOM 节点；render() 重建页面后仍能准确定位。 */
    if(n) return `.flow-sec[data-flow="${CSS.escape ? CSS.escape(String(n)) : String(n)}"]`;
    return sec;
  }
  return btn.id ? `#${CSS.escape ? CSS.escape(btn.id) : btn.id}` : btn;
}
function optButtonStateClass(){
  const b=$('#btnOptimizationConcept');
  if(!b) return;
  b.classList.add('app-opt-btn');
  b.classList.remove('app-opt-btn-legacy','app-opt-btn');
  b.classList.add('app-opt-btn');
  const generating=state.polishStatus==='generating'||state.strategyStage1Status==='generating'||state.strategyStage2Status==='generating';
  const error=state.polishStatus==='error'||state.strategyStage1Status==='error'||state.strategyStage2Status==='error';
  const ready=state.polishOptions?.length && (state.polishStatus==='adopted'||state.polishStatus==='ready_single'||state.polishStatus==='waiting_selection'||state.strategyStage2Status==='ready'||state.strategyStage2Status==='adopted');
  b.classList.toggle('app-opt-idle',!generating&&!error&&!ready);
  b.classList.toggle('app-opt-generating',!!generating);
  b.classList.toggle('app-opt-ready',!!ready&&!generating&&!error);
  b.classList.toggle('app-opt-error',!!error&&!generating&&!ready);
}
function busy(btn, on, label, cls){
  if(!btn) return;
  installGlobalGenerationUi();
  if(on){
    btn._txt = btn.innerHTML; btn._generationFocusTarget = inferGenerationFocusTarget(btn); btn.disabled = true;
    btn.classList.add('is-busy'); if(cls) btn.classList.add(cls);
    btn.innerHTML = '<span class="spinner"></span>'+(label||'生成中…');
    if(btn.id==='btnOptimizationConcept'){
      btn.classList.add('app-opt-btn','app-opt-generating');
      btn.classList.remove('app-opt-idle','app-opt-ready','app-opt-error');
      btn.classList.add('app-opt-pressed');
      setTimeout(()=>btn.classList.remove('app-opt-pressed'),320);
    }
  } else {
    btn.disabled = false; btn.classList.remove('is-busy'); if(cls) btn.classList.remove(cls); if(btn._txt!=null) btn.innerHTML = btn._txt;
    if(btn.id==='btnOptimizationConcept') optButtonStateClass();
    if(btn._generationFocusTarget) queueGenerationFocus(btn._generationFocusTarget,90);
  }
}
installGlobalGenerationUi();

let _abortCtl = null;           // 当前 AbortController
let _abortBtn = null;           // 当前可见的停止按钮 DOM
function makeStopBtn(){
  const b = document.createElement('button');
  b.type = 'button'; b.className = 'stop-btn'; b.innerHTML = '⏹';
  b.onclick = ()=>{
    if(_abortCtl){ _abortCtl.abort(); _abortCtl = null; }
    hideStopBtn();
  };
  b.style.display = 'none';
  return b;
}
function showStopBtn(parent){
  if(!_abortBtn){ _abortBtn = makeStopBtn(); document.body.appendChild(_abortBtn); }
  _abortCtl = new AbortController();
  _abortBtn.style.display = '';
  parent.appendChild(_abortBtn);
}
function hideStopBtn(){
  if(_abortBtn){ _abortBtn.style.display = 'none'; }
  _abortCtl = null;
}
let _aiOptBusy = false;
function genBusy(){
  if(_aiOptBusy) return true;
  if(_abortCtl) return true;
  const busyAny = document.querySelector('.is-busy, [disabled].cp-gen-btn-loading');
  if(busyAny) return true;
  return false;
}
function guardSwitchStep(){
  if(genBusy()){
    return confirm('当前有生成任务进行中，切换视图会中断其运行，确定继续？');
  }
  return true;
}



const CHAPTER_ENDING_CONTRACT_VERSION = 'app5-ending-stop-boundary-v3-transition-chain';
const CHAPTER_ENDING_CONTRACT = Object.freeze({
  version: CHAPTER_ENDING_CONTRACT_VERSION,
  command: '最后有效事件即终止边界，边界之后不得新增任何叙事功能',
  authority: 'single_source',
  rule: '章末只在本章最后一个已经发生的有效事件/变化处自然停止。最后有效事件一旦完成，立即视为终止边界；边界之后不得再添加任何作者式总结、未来展望、正能量升华、希望/期待/憧憬/满意/高兴/想象、人生感悟、价值判断、命运判断、意义解释、下一步暗示或读者情绪引导。下一章可以承接，但承接点必须来自终止边界前已经发生并成立的事实、状态、关系、信息、动作、环境或直接后果；不得为了“承接”再另起一个作者式钩子。',
  positive: [
    '事件完成：停在已经发生的结果，例如门锁扣上、文件交出去、伤口被处理完。',
    '决定成立：停在人物已经做出的决定或动作，例如把签好的文件推过去，不补“以后会怎样”。',
    '关系变化：停在当下互动，例如对方第一次没有收回手，不把关系升华成未来宣言。',
    '信息成立：停在新事实被确认，例如电话报出一个地址，地址已经被记下。',
    '直接后果：停在已经发生的后果，例如警报响起、玻璃碎裂、门被推开。',
    '冲突停住：停在当前僵持、拒绝、沉默或动作未完成的事实，不追加“接下来一定会……”的感觉。',
    '物件变化：停在证据、信件、钥匙、药片等具体状态发生变化。',
    '认识变化：只写人物当下已经发生的意识变化；如果该意识已经完成，不再追加解释其意义。',
    '情绪可以停在最后一个真实事件内部，但不得在事件结束后另起一句/一段，把情绪包装成未来希望、满足、幸福、憧憬或人生意义。',
    '如果最后一个有效事件已经结束，最安全的结尾是直接停止；不要为了“文学性”再补一句总结。',
    '下一章承接不是单一模式：可以承接事件未完、已揭示的新信息、正在进行的动作、关系变化、物件/线索、环境状态、冲突停滞、问题悬置、信息缺口、情绪未决、选择未决、直接后果、时间切换、场景切换、冷收束、平淡状态、不确定状态、失败/损失/危险/僵局等。',
    '承接方式由本章真实发生的最后状态决定，不要求每章都留下悬念，更不要求每章留下希望、期待、兴奋或正能量。',
    '“给下一章留下东西”与“制造读者等待感”不是同一件事：前者允许，后者禁止。',
    '如果本章最后状态本身已经自然提供了下一章的入口，可以保留这个入口；不得在入口之外额外解释“为什么下一章一定值得期待”。'
  ],
  feelingFailures: [
    '为了让读者继续读而故意留下“下一步一定有事”的感觉。',
    '把本章已经结束的事件再包一层“新的开始/命运改变/真正故事开始”的感觉。',
    '即使完全不用“期待、未来、明天、希望、悬念”等词，只要读者读完明显被推向“等下一章”的情绪，也算失败。',
    '为了形成钩子而额外增加一个本章没有发生的新问题、新承诺、新预告或抽象前瞻。',
    '在最后有效事件之后新增总结性情绪句，即使没有明显未来词，也属于越过终止边界。',
    '用也许、或许、从此、终于、第一次、总会、终会、未来、以后、明天、将来、命运、人生等抽象词把当前事件升华为正面结论，也属于越界。'
  ],
  counterExamples: [
    '失败：她把信收进抽屉，忽然觉得从这一刻起，一切都会不同。——这是未来指向感觉。',
    '失败：门关上了，真正的故事才刚刚开始。——这是强行下一章钩子。',
    '失败：他没有再说话，只等着接下来会发生什么。——即使没有“未来”二字，仍在要求读者等待。',
    '失败：她握紧钥匙，命运的齿轮已经转动。——抽象升华替代了具体收束。',
    '失败：她把门关上，心里第一次对未来有了期待。——真实动作已经结束，后一句是新增的未来/情绪总结。',
    '失败：他收好文件，忽然觉得一切都会慢慢好起来。——事件结束后追加正能量结论。',
    '失败：她看着灯光，嘴角带着满足的笑意，也许明天会更好。——情绪升华加未来展望双重越界。'
  ],
  audit: '审计只验证正文是否服从本契约；词汇仅作辅助证据。核心判据是：最后有效事件之后是否新增叙事功能。只要新增总结/升华/未来/情绪引导，即使换词规避，也判定失败。'
});
function chapterEndingContractText(){
  return `【唯一章末口令｜${CHAPTER_ENDING_CONTRACT_VERSION}】\n口令：${CHAPTER_ENDING_CONTRACT.command}\n${CHAPTER_ENDING_CONTRACT.rule}\n正向写法：\n${CHAPTER_ENDING_CONTRACT.positive.map(x=>' - '+x).join('\\n')}\n感觉级失败判定：\n${CHAPTER_ENDING_CONTRACT.feelingFailures.map(x=>' - '+x).join('\\n')}\n反例：\n${CHAPTER_ENDING_CONTRACT.counterExamples.map(x=>' - '+x).join('\\n')}\n唯一职责链：上游生成/选择停止点 → 老师施工最后有效事件 → 正文自然停止 → 审计只验证契约。其他层不得另立章末主口令。`;
}
function normalizeChapterEndingContract(plan){
  const p=plan&&typeof plan==='object'?plan:{};
  return {version:CHAPTER_ENDING_CONTRACT_VERSION, command:CHAPTER_ENDING_CONTRACT.command,
    lastEffectiveEvent:String(p.lastEffectiveEvent||'').trim(), form:String(p.form||'自然停止').trim(),
    endingFunction:String(p.endingFunction||'completion').trim(), positiveExamples:CHAPTER_ENDING_CONTRACT.positive.slice(),
    hook:false, transitionModes:CHAPTER_ENDING_TRANSITION_MODES.map(x=>x.key),
    previousEndingType:String(p.previousEndingType||'').trim(), transitionType:String(p.transitionType||'').trim(), transitionBasis:String(p.transitionBasis||'').trim(),
    nextTransitionType:String(p.nextTransitionType||'').trim(), nextTransitionBasis:String(p.nextTransitionBasis||'').trim(), allowedTransition:String(p.allowedTransition||'').trim(),
    forbiddenFeeling:CHAPTER_ENDING_CONTRACT.feelingFailures.slice()};
}

const CHAPTER_ENDING_WRITER_RULES = `
${chapterEndingContractText()}
`;
const LONG_CHAPTER_SYS_PRO = `你是长篇小说创作链中的“正文作家”。你的职责不是规划故事，而是把已经确定的故事写成自然、完整、可阅读的小说正文。

【一、身份与权限】
你只负责文学现场执行，不承担校长、老师、世界观设计师或下一章策划者的职责。

信息权威按以下层级理解：
L1【世界事实层】词典正式世界观规则、正式人物/地点/专名/设定，以及已经成立的剧情事实。它回答“这个世界是什么样”。不得擅自改写、另造或解释成另一套规则。
L2【动态真实状态层】上一章已经写成的真实状态、当前人物状态、时间与实际剧情位置。它回答“故事现在实际在哪里”。不得为了配合计划而篡改已经发生的事实。
L3【本章规划层】老师本章原始教案，是本章剧情与施工方向的唯一规划来源。老师已经完成的章节规划不得被重新设计、重排或另建第二套方案。
L4【文学表达层】语言、对白、场景、动作、心理、感官、节奏、情绪与自然过渡。这里是正文AI可以自由发挥的空间。

【二、老师教案是本章规划权威】
正文AI必须读取老师提供的本章原始教案，理解并执行其中已经确定的本章任务、事件、人物行动、因果关系与章末状态。
不得重新规划章节，不得重新安排主线，不得重新分配GLOBAL/HYBRID/CHAPTER，不得重新决定风格词条，不得生成第二份教案、第二套剧情骨架、施工单或场景计划。

【三、世界观规则的唯一来源】
词典中的正式世界观规则是规则本身。老师的“世界观规则执行说明”只是本章如何落实正式规则的施工说明，不是第二套世界观。正文AI负责把正式规则及老师本章执行说明自然写进剧情，不得另造第三套规则。

【四、文学发挥范围】
在不改变世界事实、已发生事实、老师本章主要事件与章末状态的前提下，可以自然补充人物反应、合理对白、潜台词、环境互动、感官细节、局部误解、合理失败尝试、短暂障碍、自然动作和过渡，让故事像真实发生过一样。
不得凭空建立会持续影响后续章节的新核心事实，不得让临时细节抢占主线。

【五、写作风格】
写作风格属于文学表达层。在文学表达层内部，当前有效写作风格优先于普通表达习惯；但写作风格不能覆盖世界事实、动态真实状态或老师本章规划。

【六、开篇与承接】
先理解系统提供的上一章真实状态、上一章结尾接力、当前人物状态、时间边界和本章教案，再从真实承接点自然开笔。若存在时空跨度，用简洁自然的文字完成过桥，不为了过桥而增加无关剧情。

【七、自然写作】
按老师教案已经确定的主线自然推进。不要输出分析、计划、节拍标签、后台术语或结构化教案。不要机械按内部结构逐项罗列。正文应始终是连续、自然的小说文本。

【八、结束条件】
当本章最后一个必要事件完成、老师规定的章末状态成立后自然结束。不要为了凑字数继续扩写，不推进下一章。

【九、最终输出】
只输出本章小说正文。不要解释自己的工作，不要输出SYSTEM/USER内容，不要输出任何后台分析、工作说明或系统内部过程。`;




