function refreshPrincipalUi(){
  const principalGenerateBtn = document.querySelector('[data-scp-principal-generate]');
  if(!principalGenerateBtn) return;
  const st = getSchoolStepStatus('principal');
  principalGenerateBtn.classList.toggle('running', st.isRunning);
  principalGenerateBtn.classList.toggle('done', st.isDone);
  principalGenerateBtn.disabled = !!st.isRunning;
  principalGenerateBtn.innerHTML = st.isRunning ? '⏳ 校长生成中…' : (st.isDone ? '👑 重新生成校长' : '👑 生成校长');
}

function refreshTeacherUi(i){
  const tBtn = document.querySelector(`[data-scp-teacher="${i}"]`);
  if(!tBtn) return;
  const done = scDone('t'+i);
  tBtn.classList.toggle('done', done);
  const activeSchoolRun = state._schoolRunning || null;
  tBtn.classList.toggle('running', !!(activeSchoolRun && activeSchoolRun.activeKey === 't'+i));
  tBtn.disabled = !!(activeSchoolRun && activeSchoolRun.activeKey === 't'+i);
}

function refreshTeacherBatchUi(){
  const tb=document.querySelector('[data-scp-teacher-all]');
  if(!tb) return;
  const st=teacherBatchButtonState();
  tb.classList.toggle('running',st.running);
  tb.classList.toggle('done',st.allDone && !st.running);
  tb.disabled=!!st.running;
  tb.innerHTML=st.running ? `🎓 一键老师进行中（${st.completed}/${st.total}）…` : (st.allDone ? '✓ 一键老师已完成' : '🎓 一键老师');
}

function refreshAllTeacherUi(){
  const groups = teacherAssignmentGroups();
  groups.forEach((g,i)=>refreshTeacherUi(i));
  refreshTeacherBatchUi();
}

function teacherBatchButtonState(){
  const groups=teacherAssignmentGroups();
  const running=!!state._teacherBatchRunning;
  const allDone=groups.length>0 && groups.every((g,i)=>scTeacherGroupComplete(i));
  const completed=groups.filter((g,i)=>scTeacherGroupComplete(i)).length;
  return {groups,running,allDone,completed,total:groups.length};
}
async function genSchoolTeachersBatch(){
  if(genBusy() || state._teacherBatchRunning){ toast('已有生成任务进行中，请稍候'); return; }
  const groups=teacherAssignmentGroups(); if(!groups.length){toast('请先填写章节数，才能一键老师');return;}
  if(!scDone('principal')){toast('请先完成校长；老师只读取“读校长成果”当前保存版本。');return;}
  state._teacherBatchRunning={startedAt:Date.now(),total:groups.length,completed:0};
  refreshTeacherBatchUi();
  try{
    for(let i=0;i<groups.length;i++){
      if(scTeacherGroupComplete(i)) { state._teacherBatchRunning.completed++; refreshTeacherUi(i); refreshTeacherBatchUi(); continue; }
      state._schoolRunning={activeKey:'t'+i,teacherIndex:i,stepIndex:0,totalSteps:groups.length,label:groups.length>1?`老师${i+1}（${groups[i].teacherCode}）`:'老师'};
      refreshTeacherUi(i); refreshTeacherBatchUi();
      const ok=await genTeacher(null,i);
      if(ok){ scMark('t'+i,true,false); state._teacherBatchRunning.completed++; }
      else { scSetFailed('t'+i,true); }
      persist(); refreshTeacherUi(i); renderTeacherCutUi(i); refreshTeacherBatchUi();
      // 单个老师失败只记录该老师，继续下一位，不阻塞其他老师。
    }
    const allDone=groups.every((g,i)=>scTeacherGroupComplete(i));
    if(allDone) scMark('teacher',true,false); else delete scState().finished.teacher;
    persist();
    groups.forEach((g,i)=>renderTeacherCutUi(i));
    refreshTeacherBatchUi();
    toast(allDone?'一键老师已完成全部老师教案。':'一键老师已完成可用老师；失败老师可单独重试。');
  }finally{
    state._schoolRunning=null; state._teacherBatchRunning=null; hideStopBtn(); refreshAllTeacherUi();
  }
}

function bindSchoolSteps(){
  const teacherAllBtn=$('[data-scp-teacher-all]'); if(teacherAllBtn && !teacherAllBtn._bound){ teacherAllBtn._bound=true; teacherAllBtn.onclick=()=>genSchoolTeachersBatch(); }
  const applyBtn = $('[data-scp-apply-titles]');
  if(applyBtn) applyBtn.onclick = ()=> applyPrincipalTitles();
  const principalGenerateBtn = $('[data-scp-principal-generate]');
  if(principalGenerateBtn && !principalGenerateBtn._pgB){
    principalGenerateBtn._pgB = 1;
    principalGenerateBtn.onclick = async ()=>{
      const btn = principalGenerateBtn;
      if(btn.disabled) return;
      scSetFailed('principal', false);
      state._schoolRunning = { activeKey:'principal', stepIndex:2, totalSteps:3, label:'校长' };
      refreshPrincipalUi();
      try {
        const ok = await genPrincipal(btn);
        if(ok){
          scMark('principal', true);
          const titles = (state.school && state.school.principal && Array.isArray(state.school.principal.titles)) ? state.school.principal.titles : [];
          if(titles.length && !isPrincipalTitlesApplied()) doApplyTitles(titles, { silent:true });
          playDoneSound('single');
        } else {
          scSetFailed('principal', true);
        }
      } catch(e){
        console.error('[principalGenerateButton]', e);
        scSetFailed('principal', true);
      } finally {
        state._schoolRunning = null;
        refreshPrincipalUi();
      }
    };
  }
  $$('[data-scp-step]').forEach(btn=>{
    if(btn._sB) return; btn._sB = 1;
    btn.onclick = async ()=>{
      const step = btn.dataset.scpStep;
      if(step === 'teacher' || step === 'teacherAll'){ await genSchoolTeachersBatch(); return; }
      if(step === 'teacherSingle'){
        const gi = Number(btn.dataset.scpTeacher);
        const ok = await genTeacher(btn, gi);
        if(ok){
          scMark('t'+gi, true);
          const groups = teacherAssignmentGroups();
          if(groups.every((g,i)=>scDone('t'+i))) scMark('teacher', true);
        }
        refreshTeacherUi(gi);
        return;
      }
    };
  });
  // 493：改为事件委托，避免学校卡片 render() 后按钮重新生成而丢失 click 绑定。
  if(!document._teacherCutDelegate){
    document._teacherCutDelegate=1;
    document.addEventListener('click',e=>{
      const b=e.target.closest?.('[data-scp-cut-teacher]');
      if(!b) return;
      if(b.disabled) return;
      e.preventDefault(); e.stopPropagation();
      openTeacherCutConfirm(Number(b.dataset.scpCutTeacher));
    },true);
  }
  $$('[data-scp-cut-teacher]').forEach(b=>{ if(b._cutB) return; b._cutB=1; b.onclick=e=>{ e.preventDefault(); e.stopPropagation(); }; });
  $$('[data-scp-cut-more]').forEach(b=>{ if(b._moreB) return; b._moreB=1; b.onclick=()=>{ const card=b.closest('[data-scp-teacher-card]'); const list=card?.querySelector('[data-scp-cut-list]'); if(!list) return; const on=list.style.display!=='none'; list.style.display=on?'none':''; b.textContent=on?'查看详情 ▾':'收起详情 ▴'; }; });
  $$('[data-scp-plan]').forEach(b=>{ b.onclick = ()=> openSchoolPlanReader(+b.dataset.scpPlan); });
  if(!document._teacherInjectionDelegate){
    document._teacherInjectionDelegate=1;
    document.addEventListener('click',e=>{
      const b=e.target.closest?.('[data-scp-injection-export]');
      if(!b) return;
      e.preventDefault(); e.stopPropagation();
      openTeacherInjectionExport(Number(b.dataset.scpInjectionExport));
    },true);
  }
  const pv = $('[data-scp-plan-pr]');
  if(pv) pv.onclick = ()=> openSchoolPrincipalReader();
  if(!document._principalInjectionDelegate){
    document._principalInjectionDelegate=1;
    document.addEventListener('click',e=>{
      const b=e.target.closest?.('[data-scp-principal-injection]');
      if(!b) return;
      e.preventDefault(); e.stopPropagation();
      openPrincipalInjectionExport();
    },true);
  }
  const mbh = $('[data-microbeat-fold]');
  if(mbh && !mbh._mbFold){
    mbh._mbFold=1;
    const toggleMicroBeat=()=>{ state.microBeatCollapsed=!state.microBeatCollapsed; persist(); const body=mbh.closest('.cp-card')?.querySelector('.cp-body'); if(body) body.hidden=state.microBeatCollapsed; const ico=mbh.querySelector('.sc-fold-ico'); if(ico) ico.textContent=state.microBeatCollapsed?'▸':'▾'; };
    mbh.onclick=toggleMicroBeat;
    mbh.onkeydown=e=>{ if(e.key==='Enter'||e.key===' '){ e.preventDefault(); toggleMicroBeat(); } };
  }
}

function principalCurrentResult(){
  const sc=scState();
  const p=sc && sc.principal;
  if(!p || !String(p.raw||'').trim()) return null;
  return p;
}
function getPrincipalReaderTarget(){
  const sc=scState();
  if(!sc || typeof sc!=='object') return null;
  if(!sc.principal || typeof sc.principal!=='object') sc.principal={};
  return sc.principal;
}
function saveCurrentPrincipalResult(raw, reason, target){
  const p=target || principalCurrentResult();
  if(!p) throw new Error('当前“读校长成果”不存在，无法保存');
  const nextRaw=String(raw||'').trim();
  if(!nextRaw) throw new Error('校长成果不能为空');
  // 1.0.539：原先成果只在第一次建立时锁定；手动保存绝不能覆盖原先成果。
  if(typeof p.originalRaw!=='string' || !p.originalRaw.trim()) p.originalRaw=String(p.raw||'');
  p.raw=nextRaw;
  // 人工编辑校长成果后，同步刷新现有结构化路由缓存；不新建第二套三层来源。
  try{
    const a=buildTeacherAssignment();
    const parsed=parsePrincipalStrategyMachine(nextRaw, Number(p.targetChapterCount||principalTargetChapterCount()||0), a);
    if(parsed?.valid) p.styleStrategy=parsed.styleStrategy;
    const pm=parsePrincipalMachine(nextRaw, Number(p.targetChapterCount||principalTargetChapterCount()||0), a, p.styleStrategy||{});
    if(pm){ p.plans=normalizePrincipalPlans(pm); p.chapterStrategies=buildChapterStrategiesFromPrincipal(p.plans, Number(p.targetChapterCount||principalTargetChapterCount()||0)); }
  }catch(e){ console.debug('[Principal save] 三层结构同步失败，保留原结构缓存',e); }
  p.ts=Date.now();
  p.updatedAt=Date.now();
  p.updateReason=reason||'manual_edit';
  p.parseStatus='manual_edit';
  p.status='ADOPTED';
  p.qcStatus='NOT_REQUIRED';
  p.folded=false;
  storyState().canon.principalAt=Date.now();
  storyState().pipelineVersion=(Number(storyState().pipelineVersion)||0)+1;
  storyState().docs=storyState().docs||{};
  if(storyState().docs.schoolPlan){
    storyState().docs.schoolPlan.ts=Date.now();
  }
  scMark('principal',true,false);
  markAIDone('principal',false);
  scSetError('principal',null,false,false);
  persist();
  refreshPrincipalUi();
  return p;
}
function restoreOriginalPrincipalResult(target){
  const p=target || principalCurrentResult();
  if(!p) throw new Error('当前“读校长成果”不存在，无法恢复');
  const original=String(p.originalRaw||'').trim();
  if(!original) throw new Error('当前没有可恢复的原先成果');
  return saveCurrentPrincipalResult(original,'restore_original',p);
}

function principalInjectionData(){
  const injection=buildPrincipalInjection();
  if(!injection) return null;
  return {system:String(injection.system||''),user:String(injection.user||''),label:'校长'};
}
function optimizationInjectionData(){
  const snap=state.polishInjectionSnapshot;
  if(snap && typeof snap==='object' && String(snap.system||'').trim() && String(snap.user||'').trim()){
    return {system:String(snap.system),user:String(snap.user),mode:String(snap.mode||state.polishMode||'single'),createdAt:Number(snap.createdAt)||0,fromSnapshot:true};
  }
  // 兼容没有快照的旧项目：只在用户点击导出时重新组装当前真实生成路径，不调用AI。
  const ctx={originalAnchors:null,strategicDimensions:[],diversityProfile:null};
  try{
    return {system:String(getSystemPrompt('ideaOptimization',ctx)+globalCreativeConstraintBlock('ideaOptimization')||''),user:String(buildAIPrompt('ideaOptimization',ctx)||''),mode:'four',createdAt:0,fromSnapshot:false};
  }catch(e){ return null; }
}
function optimizationInjectionFileName(){ return `优化构想_注入_${Date.now()}.txt`; }
