function polishCandidateToStructuredText(o, index){
  const b=o?.structuredBlueprint||{}; const lines=[];
  const kv=(obj)=>Object.entries(obj||{}).filter(([,v])=>v!==undefined&&v!==null&&String(v).trim()!=='').map(([k,v])=>`${k}：${typeof v==='string'?v:JSON.stringify(v)}`);
  const list=(arr,mapper)=>Array.isArray(arr)?arr.map(mapper).filter(Boolean):[];
  lines.push(`[OPTION_META]`,`name：${String(o?.name||`方案${index+1}`)}`,`bookTitle：${String(o?.bookTitle||b.optionMeta?.bookTitle||'')}`,'[/OPTION_META]');
  lines.push(`[STORY_CORE]`,...kv(b.storyCore),'[/STORY_CORE]');
  lines.push(`[PROTAGONIST]`,...kv(b.protagonist),'[/PROTAGONIST]');
  lines.push(`[KEY_CHARACTERS]`,...list(b.keyCharacters,x=>`- ${[x?.name,x?.identity,x?.role,x?.relation].map(v=>String(v||'')).join('｜')}`),'[/KEY_CHARACTERS]');
  lines.push(`[RELATIONSHIPS]`,...list(b.relationships,x=>`- ${[x?.from,x?.to,x?.relation].map(v=>String(v||'')).join('｜')}`),'[/RELATIONSHIPS]');
  lines.push(`[WORLD]`,...kv(b.world),'[/WORLD]');
  lines.push(`[CONFLICT]`,...kv(b.conflict),'[/CONFLICT]');
  lines.push(`[STORY_ARC]`,...kv(b.storyArc),'[/STORY_ARC]');
  lines.push(`[FULL_BOOK_BEAT]`,...list(b.fullBookBeat,x=>`- ${String(x||'')}`),'[/FULL_BOOK_BEAT]');
  const wsp=b.writingStyleInheritanceSupplement||o?.writingStyleInheritanceSupplement||{};
  lines.push(`[WRITING_STYLE_INHERITANCE_SUPPLEMENT]`,`source：${String(wsp.source||'optimization_concept')}`,`supplementStatus：${String(wsp.supplementStatus||'none')}`,'INHERITANCE',...list(wsp.inheritance,x=>`- ${[x?.id,x?.name,x?.definition,x?.attributes,x?.features,x?.manifestations,x?.examples].map(v=>String(v||'')).join('｜')}`),'SUPPLEMENTS',...list(wsp.supplements,x=>`- ${[x?.id,x?.name,x?.definition,x?.attributes,x?.features,x?.manifestations,x?.examples,x?.reason].map(v=>String(v||'')).join('｜')}`),'[/WRITING_STYLE_INHERITANCE_SUPPLEMENT]');
  return lines.join('\n');
}
function polishOptionsToStructuredText(){
  const opts=Array.isArray(state.polishOptions)?state.polishOptions:[];
  if(!opts.length) return '';
  const out=[polishAnalysisHeader(),''];
  opts.forEach((o,i)=>{ out.push(`【方案${i+1}｜${o.name||`方案${i+1}`}】`,polishCandidateToStructuredText(o,i),''); });
  return out.join('\n').trim();
}
function polishAnalysisHeader(){
  const analysis=Array.isArray(state.polishOptions)&&state.polishOptions[0]?.originalAnchors ? state.polishOptions[0].originalAnchors : (state.originalIdeaAnchors||{});
  const dims=Array.isArray(state.strategicDimensions)&&state.strategicDimensions.length ? state.strategicDimensions : ((state.polishOptions||[])[0]?.strategicDimensions||[]);
  const dp=(state.strategicDiversityProfile||((state.polishOptions||[])[0]?.diversityProfile)||{});
  return ['【原始构想锚点】',`人物：${(analysis.characters||[]).join('、')}`,`关系：${(analysis.relationships||[]).join('、')}`,`目标：${(analysis.goals||[]).join('、')}`,`核心冲突：${analysis.coreConflict||''}`,`固定事实：${(analysis.fixedFacts||[]).join('、')}`,'','【动态战略维度】',...dims.map(d=>`- ${d?.name||''}｜${d?.description||''}｜契合：${d?.whyFit||''}`),'','【战略多样性】',`固定核心：${(dp.fixedCore||[]).join('、')}`,`可变轴：${(dp.variableAxes||[]).join('、')}`,`避免重复：${(dp.avoidRepetition||[]).join('、')}`,`推荐组合：${dp.recommendedMix||''}`,''].join('\n');
}
function parseEditedPolishText(text,multi,allowSingle,strictParallel=true){
  const src=String(text||'').trim();
  if(multi || /【原始构想锚点】|【动态战略维度】|【战略多样性】/i.test(src)) return parseOptimizationPlainText(src,!!multi,!!allowSingle,strictParallel);
  return parseOptimizationPlainText(`${polishAnalysisHeader()}\n${src}`,false,!!allowSingle,strictParallel);
}
async function readTextFileForImport(acceptExts=['.txt','.md','.markdown']){
  return await new Promise((resolve,reject)=>{
    const input=document.createElement('input'); input.type='file'; input.accept=acceptExts.join(',');
    input.onchange=async()=>{
      const file=input.files&&input.files[0];
      if(!file){ reject(new Error('未选择文件')); return; }
      const name=String(file.name||'').toLowerCase();
      if(!acceptExts.some(ext=>name.endsWith(ext))){ reject(new Error('只支持 TXT / MD / MARKDOWN 文件')); return; }
      try{
        let text=String(await file.text()||'').replace(/^\uFEFF/,'').replace(/\r\n/g,'\n').replace(/\r/g,'\n');
        if(!text.trim()){ reject(new Error('导入文件内容为空')); return; }
        resolve({name:file.name,text});
      }catch(e){ reject(new Error('文件读取失败：'+String(e?.message||e))); }
    };
    input.onerror=()=>reject(new Error('文件读取失败'));
    input.click();
  });
}
function getOptimizationReaderState(){
  const opts=Array.isArray(state.polishOptions)?state.polishOptions:[];
  const selected=state.polishSelectedFinal ? JSON.parse(JSON.stringify(state.polishSelectedFinal)) : null;
  return {
    multi: JSON.parse(JSON.stringify(opts)),
    final: selected,
    selectedId: state.polishSelectedId||null
  };
}
function createOptimizationReaderBaselines(){
  const data=getOptimizationReaderState();
  return {
    multi: JSON.parse(JSON.stringify(data.multi)),
    final: JSON.parse(JSON.stringify(data.final)),
    selectedId:data.selectedId
  };
}
function renderOptimizationMultiCard(card, draft){
  if(!card) return;
  const text=Array.isArray(draft)&&draft.length ? draft.map((o,i)=>polishCandidateToStructuredText(o,i)).join('\n\n') : '';
  card.querySelector('[data-or-multi-text]').value=text;
}
function renderOptimizationFinalCard(card, draft, optionIndex){
  if(!card) return;
  card.querySelector('[data-or-final-text]').value=draft ? polishCandidateToStructuredText(draft,Math.max(0,optionIndex||0)) : '';
}
function parseOptimizationReaderText(text, multi){
  const src=String(text||'').trim();
  if(!src) throw new Error(multi?'没有有效的多方案':'没有有效的最终方案');
  const normalized = multi ? src : `【方案1｜最终方案】\n${src}`;
  // 用户 Reader 是人工编辑入口：仍要求能识别标准四方案/单方案结构，但不再把结构块之外的用户补充文字误判为“AI第二版本”。
  const parsed=parseEditedPolishText(normalized,!!multi,!multi,false);
  if(!parsed?.ok) throw new Error(parsed?.error||'结构化纯文本解析失败');
  if(!Array.isArray(parsed.options)||!parsed.options.length) throw new Error(multi?'没有有效的多方案':'没有有效的最终方案');
  if(multi && parsed.options.length!==4) throw new Error(`多方案必须包含4个方案，当前解析到${parsed.options.length}个`);
  return parsed.options;
}
function adoptOptimizationOption(selectedOptionIndex){
  const opts=Array.isArray(state.polishOptions)?state.polishOptions:[];
  const index=Number(selectedOptionIndex);
  if(!Number.isInteger(index)||index<1||index>opts.length){ toast('请输入有效的方案编号'); return false; }
  const source=opts[index-1];
  if(!source){ toast('对应方案不存在'); return false; }
  const copy=JSON.parse(JSON.stringify(source));
  state.polishSelectedId=source._id||null;
  state.polishAdopted=source.name||`方案${index}`;
  state.polishStatus='adopted';
  state.strategyStage2Status='adopted';
  state.polishRevision=Number(state.polishRevision||0)+1;
  state.polishSelectedFinal=copy;
  syncPolishMetaFromCandidate(copy);
  rebuildCanonicalFromSelectedFinal();
  invalidateAfterStoryStrategyChange();
  persist();
  render();
  return true;
}
function rebuildCanonicalFromSelectedFinal(){
  const final=state.polishSelectedFinal;
  if(!final || typeof final!=='object'){ state.canonicalStoryStrategy=null; return null; }
  state.canonicalStoryStrategy=buildPolishCanonical(final,state.polishRevision);
  state.canonicalStoryStrategy=Object.assign({},state.canonicalStoryStrategy,{sourceType:'canonical_story_strategy',sourceVersion:'phase5',sourceOfTruth:'polishSelectedFinal',machineTrace:Object.assign({},state.canonicalStoryStrategy.machineTrace||{},{status:'adopted'})});
  return state.canonicalStoryStrategy;
}
function saveOptimizationMulti(draftText){
  const parsed=parseOptimizationReaderText(draftText,true);
  const old=Array.isArray(state.polishOptions)?state.polishOptions:[];
  state.polishOptions=parsed.map((o,i)=>Object.assign({},old[i]||{},o,{_id:String(old[i]?._id||('polish-'+Date.now()+'-'+i)),name:String(o.name||old[i]?.name||`方案${i+1}`),_v45:(old[i]&&old[i]._v45)?old[i]._v45:{}}));
  persist(); render();
  return state.polishOptions;
}
function restoreOptimizationMulti(baseline){
  state.polishOptions=JSON.parse(JSON.stringify(baseline||[]));
  persist(); render();
  return state.polishOptions;
}
async function importOptimizationMulti(){
  const picked=await readTextFileForImport();
  return saveOptimizationMulti(picked.text);
}
function saveOptimizationFinal(draftText){
  const parsed=parseOptimizationReaderText(draftText,false);
  const old=state.polishSelectedFinal && typeof state.polishSelectedFinal==='object' ? state.polishSelectedFinal : null;
  const merged=Object.assign({},old||{},parsed[0],{_id:String(old?._id||('polish-final-'+Date.now())),name:String(parsed[0].name||old?.name||'最终方案')});
  state.polishSelectedFinal=merged;
  state.polishRevision=Number(state.polishRevision||0)+1;
  rebuildCanonicalFromSelectedFinal();
  syncPolishMetaFromCandidate(merged);
  invalidateAfterStoryStrategyChange();
  persist(); render();
  return merged;
}
function restoreOptimizationFinal(baseline){
  state.polishSelectedFinal=baseline ? JSON.parse(JSON.stringify(baseline)) : null;
  if(state.polishSelectedFinal){
    state.polishRevision=Number(state.polishRevision||0)+1;
    rebuildCanonicalFromSelectedFinal();
    syncPolishMetaFromCandidate(state.polishSelectedFinal);
    invalidateAfterStoryStrategyChange();
  }
  persist(); render();
  return state.polishSelectedFinal;
}
async function importOptimizationFinal(){
  const picked=await readTextFileForImport();
  return saveOptimizationFinal(picked.text);
}
